use std::collections::HashMap;
use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Ident(String),
    Number(f64),
    Str(String),
    LParen,
    RParen,
    Comma,
    Eof,
}

#[derive(Debug)]
pub struct ParseError {
    pub line: usize,
    pub column: usize,
    pub message: String,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}:{}: {}", self.line, self.column, self.message)
    }
}

pub struct Lexer<'a> {
    input: &'a str,
    chars: std::iter::Peekable<std::str::CharIndices<'a>>,
    line: usize,
    column: usize,
}

impl<'a> Lexer<'a> {
    pub fn new(input: &'a str) -> Self {
        Self { input, chars: input.char_indices().peekable(), line: 1, column: 1 }
    }

    pub fn next_token(&mut self) -> Result<Token, ParseError> {
        self.skip_whitespace();
        let Some(&(start, c)) = self.chars.peek() else {
            return Ok(Token::Eof);
        };

        match c {
            '(' => { self.bump(); Ok(Token::LParen) }
            ')' => { self.bump(); Ok(Token::RParen) }
            ',' => { self.bump(); Ok(Token::Comma) }
            '"' => self.read_string(),
            c if c.is_ascii_digit() => self.read_number(start),
            c if c.is_alphabetic() || c == '_' => Ok(Token::Ident(self.read_while(start, |ch| ch.is_alphanumeric() || ch == '_'))),
            other => Err(self.error(format!("unexpected character {other:?}"))),
        }
    }

    fn read_number(&mut self, start: usize) -> Result<Token, ParseError> {
        let text = self.read_while(start, |ch| ch.is_ascii_digit() || ch == '.');
        text.parse::<f64>()
            .map(Token::Number)
            .map_err(|e| self.error(format!("invalid number `{text}`: {e}")))
    }

    fn error(&self, message: String) -> ParseError {
        ParseError { line: self.line, column: self.column, message }
    }
}

pub fn count_idents(tokens: &[Token]) -> HashMap<&str, usize> {
    let mut counts = HashMap::new();
    for token in tokens {
        if let Token::Ident(name) = token {
            *counts.entry(name.as_str()).or_insert(0) += 1;
        }
    }
    counts
}

//! Retry policy for the upload worker.

use anyhow::{anyhow, Context, Result};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use std::time::Duration;
use tokio::sync::{mpsc, Mutex};
use tracing::{debug, info, warn};

const MAX_ATTEMPTS: u32 = 5;
const BASE_DELAY_MS: u64 = 250;

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub struct UploadJob {
    pub id: u64,
    pub bucket: String,
    pub object_key: String,
    #[serde(default)]
    pub attempts: u32,
}

pub struct Worker<C: Client + Send + Sync + 'static> {
    client: Arc<C>,
    queue: Arc<Mutex<mpsc::Receiver<UploadJob>>>,
}

#[async_trait::async_trait]
pub trait Client {
    async fn put(&self, bucket: &str, key: &str, body: Vec<u8>) -> Result<()>;
}

impl<C: Client + Send + Sync + 'static> Worker<C> {
    pub async fn run(self: Arc<Self>) -> Result<()> {
        loop {
            let job = {
                let mut queue = self.queue.lock().await;
                match queue.recv().await {
                    Some(job) => job,
                    None => break,
                }
            };

            if let Err(err) = self.upload_with_retry(&job).await {
                warn!(job_id = job.id, error = %err, "giving up on job");
            }
        }

        info!("queue closed, worker exiting");
        Ok(())
    }

    async fn upload_with_retry(&self, job: &UploadJob) -> Result<()> {
        let body = tokio::fs::read(format!("/var/spool/uploads/{}.bin", job.id))
            .await
            .with_context(|| format!("reading payload for job {}", job.id))?;

        for attempt in 1..=MAX_ATTEMPTS {
            match self.client.put(&job.bucket, &job.object_key, body.clone()).await {
                Ok(()) => return Ok(()),
                Err(err) if attempt < MAX_ATTEMPTS => {
                    let delay = Duration::from_millis(BASE_DELAY_MS * 2u64.pow(attempt - 1));
                    debug!(attempt, ?delay, "upload failed: {err:#}");
                    tokio::time::sleep(delay).await;
                }
                Err(err) => return Err(err.context("upload failed after retries")),
            }
        }

        Err(anyhow!("unreachable: retry loop exited without a result"))
    }
}

using System.Collections.Concurrent;
using Microsoft.Extensions.Logging;

namespace Orders.Pricing;

/// <summary>
///     Calculates order totals, including tax and discounts.
/// </summary>
public sealed class OrderTotalCalculator(ITaxRateProvider taxRates, ILogger<OrderTotalCalculator> logger) : IOrderTotalCalculator
{
    private readonly ConcurrentDictionary<string, decimal> _rateCache = new(StringComparer.OrdinalIgnoreCase);

    /// <inheritdoc />
    public async Task<OrderTotal> CalculateAsync(Order order, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(order);

        if (order.Lines.Count == 0)
            return OrderTotal.Empty;

        var subtotal = order.Lines.Sum(line => line.UnitPrice * line.Quantity);
        var discount = order.Coupon is { IsActive: true } coupon ? Math.Min(subtotal, coupon.Amount) : 0m;
        var rate = await this.GetRateAsync(order.ShippingAddress.CountryCode, cancellationToken);
        var tax = Math.Round((subtotal - discount) * rate, 2, MidpointRounding.AwayFromZero);

        logger.LogDebug("Order {OrderId}: subtotal {Subtotal}, discount {Discount}, tax {Tax}", order.Id, subtotal, discount, tax);

        return new OrderTotal(subtotal, discount, tax, subtotal - discount + tax);
    }

    private async ValueTask<decimal> GetRateAsync(string countryCode, CancellationToken cancellationToken)
    {
        if (this._rateCache.TryGetValue(countryCode, out var cached))
            return cached;

        var rate = await taxRates.GetRateAsync(countryCode, cancellationToken)
            ?? throw new InvalidOperationException($"No tax rate is configured for country '{countryCode}'.");

        this._rateCache[countryCode] = rate;
        return rate;
    }
}

