    [InlineData(10, 0.80, 8)]
    [InlineData(1_000, 0.75, 750)]
    public void TriggerTokens_AreTheFloorOfMaxTimesThreshold(int maxTokens, double threshold, int expected)
    {
        // Arrange
        var budget = new ContextBudget(maxTokens, compactionThreshold: threshold);

        // Act
        var trigger = budget.CompactionTriggerTokens;

        // Assert
        trigger.Should().Be(expected);
    }

    [Fact]
    public async Task CompactAsync_WhenOlderToolResultIsOutsideBoundary_MasksIt()
    {
        // Arrange
        var messages = new List<ContextMessage>
        {
            ContextMessage.FromText(MessageRole.User, "read the file"),
            new() { Role = MessageRole.Model, Segments = [new ToolUseContent("call_1", "read_file", "{\"path\":\"a.txt\"}")] },
            new() { Role = MessageRole.Tool, Segments = [new ToolResultContent("call_1", "read_file", new string('x', 4_000))] },
            ContextMessage.FromText(MessageRole.Model, "done"),
        };
        var strategy = new SlidingWindowStrategy(new EstimatedTokenCounter(), new SlidingWindowOptions(windowSize: 1));

        // Act
        var result = await strategy.CompactAsync(messages, availableTokens: 200);

        // Assert
        result.Messages[2].State.Should().Be(CompactionState.Masked);
        result.MessagesAffected.Should().Be(1);
        result.TokensAfter.Should().BeLessThan(result.TokensBefore);
    }
}

#!/usr/bin/env python3
"""Summarise a JSON-lines log file by level and by hour."""
from __future__ import annotations

import argparse
import json
import sys
from collections import Counter, defaultdict
from datetime import datetime
from pathlib import Path


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("path", type=Path, help="log file to read")
    parser.add_argument("--level", choices=["debug", "info", "warning", "error"], default=None)
    parser.add_argument("--top", type=int, default=10, help="how many messages to show (default: %(default)s)")
    return parser.parse_args(argv)


def read_records(path: Path):
    with path.open(encoding="utf-8") as handle:
        for number, line in enumerate(handle, start=1):
            line = line.strip()
            if not line:
                continue
            try:
                yield json.loads(line)
            except json.JSONDecodeError as exc:
                print(f"{path}:{number}: skipped ({exc.msg})", file=sys.stderr)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    by_level: Counter[str] = Counter()
    by_hour: dict[str, int] = defaultdict(int)
    messages: Counter[str] = Counter()

    for record in read_records(args.path):
        level = record.get("level", "info").lower()
        if args.level and level != args.level:
            continue
        by_level[level] += 1
        stamp = datetime.fromisoformat(record["time"].replace("Z", "+00:00"))
        by_hour[stamp.strftime("%Y-%m-%d %H:00")] += 1
        messages[record.get("message", "")[:80]] += 1

    for level, count in by_level.most_common():
        print(f"{level:>8}  {count:>6}")
    for hour in sorted(by_hour):
        print(f"{hour}  {'#' * min(by_hour[hour], 60)}")
    for message, count in messages.most_common(args.top):
        print(f"{count:>6}  {message}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import { useCallback, useEffect, useMemo, useState } from "react";

interface SearchResult {
  id: string;
  title: string;
  score: number;
  tags?: string[];
}

const DEBOUNCE_MS = 250;

export function useSearch(endpoint: string, initialQuery = "") {
  const [query, setQuery] = useState(initialQuery);
  const [results, setResults] = useState<SearchResult[]>([]);
  const [error, setError] = useState<Error | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const fetchResults = useCallback(
    async (text: string, signal: AbortSignal) => {
      const url = `${endpoint}?q=${encodeURIComponent(text)}&limit=20`;
      const response = await fetch(url, { signal, headers: { Accept: "application/json" } });
      if (!response.ok) {
        throw new Error(`Search failed: ${response.status} ${response.statusText}`);
      }
      return (await response.json()) as SearchResult[];
    },
    [endpoint],
  );

  useEffect(() => {
    if (query.trim().length < 2) {
      setResults([]);
      return;
    }

    const controller = new AbortController();
    const timer = setTimeout(() => {
      setIsLoading(true);
      fetchResults(query, controller.signal)
        .then(setResults)
        .catch((err: unknown) => {
          if ((err as Error).name !== "AbortError") setError(err as Error);
        })
        .finally(() => setIsLoading(false));
    }, DEBOUNCE_MS);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query, fetchResults]);

  const best = useMemo(() => [...results].sort((a, b) => b.score - a.score)[0] ?? null, [results]);

  return { query, setQuery, results, best, error, isLoading };
}

